<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class UserController { public function index(){return view('admin.users.index',['users'=>User::latest()->paginate(12)]);} public function edit(User $user){return view('admin.users.edit',compact('user'));} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|max:150|unique:users,email','password'=>'required|string|min:8','role'=>'required|in:admin,production,inventory']);User::create($d+['status'=>'active']);return back()->with('success','User account created.');} public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|string|max:100','role'=>'required|in:admin,production,inventory','status'=>'required|in:active,inactive','password'=>'nullable|string|min:8']);$p=['name'=>$d['name'],'role'=>$d['role'],'status'=>$d['status']];if(!empty($d['password']))$p['password']=Hash::make($d['password']);$user->update($p);return back()->with('success','User account updated.');} }
